def cartesian_product(a, b):
    result = []
    for item_a in a:
        for item_b in b:
            if isinstance(item_a, tuple):
                result.append(item_a + (item_b,))
            else:
                result.append((item_a, item_b))
    return result


def cartesian_product_of_shape(dimentions, result=None):
    if not dimentions:
        yield ()
        return
    if result is None:
        first_dim = dimentions[0]
        remaining = dimentions[1:]
        for i in range(first_dim):
            for rest in cartesian_product_of_shape(remaining):
                yield (i,) + rest
